  "code": "const http = await import('node:http'); const fs = await import('node:fs'); const path = await import('node:path');
const root = 'D:/dev/ab-tasks/chessground-322-dsv4-r2';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.svg': 'image/svg+xml', '.json': 'application/json', '.map': 'application/json' };
if (!global.__srv) { global.__srv = http.createServer((req, res) => { const urlPath = decodeURIComponent(req.url.split('?')[0]); let fp = path.normalize(path.join(root, urlPath)); if (!fp.startsWith(root)) { res.writeHead(403); res.end(); return; } fs.readFile(fp, (err, data) => { if (err) { res.writeHead(404); res.end('nf'); return; } res.writeHead(200, { 'Content-Type': MIME[path.extname(fp)] || 'application/octet-stream' }); res.end(data); }); }); await new Promise(r => global.__srv.listen(0, r)); }
const port = global.__srv.address().port;
const { chromium } = await import('playwright');
var browser = await chromium.launch({ headless: true });
