const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { chromium } = require('C:/Users/lokta/AppData/Local/npm-cache/_npx/e41f203b7505f1fb/node_modules/playwright');

const root = 'D:/dev/ab-tasks/chessground-322-dsv4-r2';
const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.png': 'image/png', '.svg': 'image/svg+xml', '.json': 'application/json', '.map': 'application/json' };

const server = http.createServer((req, res) => {
  const urlPath = decodeURIComponent(req.url.split('?')[0]);
  const fp = path.normalize(path.join(root, urlPath));
  if (!fp.startsWith(root)) { res.writeHead(403); res.end(); return; }
  fs.readFile(fp, (err, data) => {
    if (err) { res.writeHead(404); res.end('nf'); return; }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(fp)] || 'application/octet-stream' });
    res.end(data);
  });
});

(async () => {
  await new Promise(r => server.listen(0, r));
  const port = server.address().port;
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  const resp = await page.goto(`http://127.0.0.1:${port}/demo.html`, { waitUntil: 'networkidle' });
  await page.waitForSelector('cg-board', { timeout: 5000 });
  await page.waitForTimeout(300);
  const result = await page.evaluate(() => ({
    boards: document.querySelectorAll('cg-board').length,
    board2Pieces: document.querySelectorAll('#board-2 piece').length,
    board3ShapeMarkers: document.querySelectorAll('#board-3 marker').length,
    bodyText: document.body.innerText.slice(0, 60),
  }));
  console.log(JSON.stringify({ httpStatus: resp.status(), ...result, errors }, null, 2));
  await browser.close();
  server.close();
})().catch(e => { console.error('SCRIPT ERROR:', e.message); process.exit(1); });

